import {LOCATIONS,ITEMS,euro} from './data.js?v=0.7.3-map1';
import {CONTRACTS,contractById,canAcceptContract,contractQuote,courierRank,jobStops,deadlineView} from './contracts.js?v=0.7.3-map1';
import {addressOf} from './orientation.js?v=0.7.3-map1';
import {deliveryPlan,transportAvailable,transportLabel,DELIVERY_PEOPLE,DELIVERY_SECONDS} from './delivery-routes.js?v=0.7.3-map1';
const location=id=>LOCATIONS.find(l=>l.id===id);
export const realTime=n=>`${Math.floor(Math.max(0,Math.ceil(n))/60)}:${String(Math.max(0,Math.ceil(n))%60).padStart(2,'0')}`;
export function careerPanel(s){const c=s.courier;return `<div class="courier-career"><div><span class="eyebrow">DEIN WEG IM LIEFERDIENST</span><h3>${courierRank(c)}</h3><p>${c.completed} Touren abgeschlossen · ${c.late} verspätet · ${c.cancelled} abgebrochen</p></div><div class="courier-score"><strong>${c.reliability}<small> / 100</small></strong><span>Zuverlässigkeit</span><progress max="100" value="${c.reliability}" aria-label="Zuverlässigkeit"></progress></div></div>`;}
export function contractCards(s,button,mode='foot',filter='all'){
 if(!transportAvailable(s,mode))mode='foot';const atOffice=!s.inside&&!s.riding&&Math.hypot(s.position.x-26,s.position.z+12)<3.1;
 const choices=`<div class="dispatch-controls"><div><span>Transportplanung</span><div class="button-row">${['foot','bike','vehicle'].map(m=>button(transportLabel(m),'courierMode',m,m===mode?'secondary active':'secondary',!transportAvailable(s,m))).join('')}</div></div><div><span>Aufträge anzeigen</span><div class="button-row">${[['all','Alle'],['relaxed','Ohne Zeitlimit'],['express','Express']].map(([id,label])=>button(label,'courierFilter',id,id===filter?'secondary active':'secondary')).join('')}</div></div></div>`;
 return choices+`<div class="cards contract-grid">${CONTRACTS.filter(c=>filter==='all'||!!c.minutes===(filter==='express')).map(c=>{
 const unlocked=canAcceptContract(c,s.courier,s.mode),capacity=s.inventory.length+c.route.length<=16&&s.inventory.reduce((n,i)=>n+ITEMS[i.id].weight*i.count,0)+c.route.length*2<=20,plan=deliveryPlan(c,s,mode);
 return `<article class="card contract-card ${unlocked?'':'contract-locked'}"><div class="contract-top"><span class="tag">${c.minutes?'EXPRESS':'LIEFERTOUR'}</span><span>${c.route.length} ${c.route.length===1?'STOPP':'STOPPS'}</span></div><h3>${c.name}</h3><p>${c.description}</p><ol class="contract-preview">${c.route.map(id=>`<li>${location(id).name}<small>${addressOf(id)} · ${DELIVERY_PEOPLE[id].name}</small></li>`).join('')}</ol><div class="route-facts"><span><strong>${plan.distance} m</strong>geplante Strecke</span><span><strong>${realTime(plan.realSeconds)} min</strong>${c.minutes?'Zeitbudget':'Richtwert'} in Echtzeit</span><span><strong>${c.route.length*2} kg</strong>Sendungen</span></div><div class="price">${euro(contractQuote(c,s.skills.logistics))}<small>Grundlohn${c.bonus?' + '+euro(c.bonus)+' Zeitbonus':''}</small></div>${c.minutes?`<p class="contract-clock">Frist: <b>${plan.deadlineMinutes} Spielmin.</b> bei ${plan.speed}× · beginnt nach der Paketübernahme.</p>`:'<p class="footnote">Ohne Zeitlimit · Zeitangabe dient zur Orientierung.</p>'}${!unlocked?`<p class="contract-requirement">Ab ${c.completed} abgeschlossenen Touren und ${c.reliability}/100 Zuverlässigkeit.</p>`:!capacity?`<p class="contract-requirement">Benötigt ${c.route.length} freie Plätze und ${c.route.length*2} kg Platz im Rucksack.</p>`:''}${button(!unlocked?'Noch nicht freigeschaltet':atOffice?'Pakete übernehmen ↗':'Paketausgabe markieren ↗',atOffice?'acceptContract':'navigate',atOffice?c.id+'|'+mode:'jobs','primary',!!s.job||!!s.workshop?.active||!unlocked||!capacity)}</article>`;
 }).join('')}</div><p class="footnote">${s.mode==='sandbox'?'Freies Spiel: Alle Touren sind freigeschaltet. ':''}Pakete trägst du mit beiden Händen: langsamer gehen, kein Sprinten oder Springen. Im Fahrzeug sind sie verstaut. Die Planung berücksichtigt das Tragetempo, Übergaben und einen Verkehrspuffer. Für Fahrzeugplanung muss dein eigenes fahrbereites Fahrzeug in der Nähe der Paketausgabe stehen (höchstens 18 m). Die Frist wird bei Annahme festgelegt; spätere Änderungen des Spieltempos verändern die verbleibende Echtzeit. Logistikerfahrung ist im Grundlohn enthalten. Lieferwagenbonus: bis zu 25 %, anteilig zur gefahrenen Strecke. Bei Verspätung entfällt der Zeitbonus, der Grundlohn bleibt. Menüs pausieren das Spiel.</p>`;
}
export function deadlineMarkup(s){const d=deadlineView(s);if(!d)return '';return `<div class="tour-deadline ${d.late?'late':d.urgent?'urgent':''}"><div><strong>${d.late?'Zeitbonus verfallen':realTime(d.realSeconds)+' Echtzeit übrig'}</strong><b class="tempo-badge">${d.speed}×</b></div><span>${d.late?'Grundlohn bleibt · Zuverlässigkeit −8':d.text+' · bis '+d.label}</span><progress max="1" value="${d.ratio}" aria-label="Verbleibende Expresszeit"></progress>${d.changedSpeed?'<small>Spieltempo seit Annahme geändert. Die vereinbarte Spielzeitfrist bleibt gleich.</small>':''}</div>`;}
export function itinerary(s,button){const j=s.job;if(!j)return '<p class="lead">Du hast gerade keinen laufenden Auftrag. Neue Liefertouren bekommst du bei Kiez & Kurier, Lindenallee 12.</p>'+button('Aufträge ansehen ↗','jobs');
 const c=contractById(j.contract),stops=jobStops(j),pickup=j.interaction?.kind==='pickup';
 if(j.type!=='courier')return '<p class="lead">'+(j.type==='cleaning'?j.progress+' / 6 Abfallsäcke gesammelt.':j.progress+' / 4 Kisten sortiert. '+(j.carrying?'Bringe die Kiste zum markierten Regal.':'Scanne die nächste Kiste am Depot.'))+'</p><div class="button-row">'+button('Zur Arbeit ↗','trackJob')+button('Auftrag abbrechen','confirmCancel','','secondary')+'</div>';
 return `<div class="tour-heading"><span class="tag">LIEFERSCHEIN</span><h3>${c?.name||'Eine sichere Zustellung'}</h3><p>${pickup?'Paketübernahme läuft · im Spiel fortsetzen':j.progress+' / '+stops.length+' übergeben · '+(stops.length-j.progress)+' Sendungen dabei'}</p></div>${deadlineMarkup(s)}${pickup?'<div class="info-box">Die Expressfrist beginnt erst, wenn Jonas dir die Sendungen übergeben hat.</div>':!c?.minutes?'<p class="footnote">'+(c?'Diese Tour hat kein Zeitlimit.':'Voller Lohn innerhalb von 6 Spielstunden.')+'</p>':''}${j.plan?`<div class="info-box">${transportLabel(j.plan.mode)} · ${j.plan.distance} m geplante Strecke<br>Weg ca. ${realTime(j.plan.travelSeconds)} min + Übergaben / Halte ${realTime(j.plan.serviceSeconds)} min + Orientierung / Verkehr ${realTime(j.plan.bufferSeconds)} min. Richtwerte in Echtzeit bei Annahme.</div>`:''}<ol class="tour-stops">${stops.map((id,i)=>`<li class="${i<j.progress?'done':i===j.progress?'current':'pending'}"><span class="stop-number">${i<j.progress?'✓':i+1}</span><div><strong>${location(id).name}</strong><span>${addressOf(id)}</span><small>${i<j.progress?'Persönlich übergeben':i===j.progress?DELIVERY_PEOPLE[id].name+' wartet am Empfang · E zur Übergabe':'Danach · noch im Rucksack'}</small></div></li>`).join('')}</ol>${c?`<div class="info-box">Grundlohn <b>${euro(j.quotedBase)}</b>${c.bonus?' · möglicher Zeitbonus <b>'+euro(c.bonus)+'</b>':''}<small>Auszahlung nach der letzten vollständigen Übergabe.</small></div>`:''}<div class="button-row">${button('Nächsten Stopp markieren ↗','trackJob')}${button('Auftrag abbrechen','confirmCancel','','secondary')}</div>`;
}
export function courierReceipt(s){
 const r=s.courier.last;if(!r)return '';const title=contractById(r.contract)?.name||'Einzellieferung';
 return `<section class="courier-receipt"><span class="eyebrow">LETZTE ABRECHNUNG · TAG ${r.day}</span><h3>${title}</h3><p>${r.status==='cancelled'?'Abgebrochen':r.status==='late'?'Verspätet zugestellt':'Erfolgreich zugestellt'} · ${r.stops} Übergabe${r.stops===1?'':'n'} · ${r.duration} Spielminuten</p><dl><div><dt>Grundlohn</dt><dd>${euro(r.base)}</dd></div><div><dt>Lieferwagenbonus</dt><dd>${euro(r.vehicleBonus)}</dd></div><div><dt>Zeitbonus${r.missedBonus?' · '+euro(r.missedBonus)+' verfallen':''}</dt><dd>${euro(r.timeBonus)}</dd></div><div class="receipt-total"><dt>Ausgezahlt</dt><dd>${euro(r.total)}</dd></div>${r.estimatedCosts!=null?`<div><dt>Geschätzter Kraftstoff / Verschleiß</dt><dd>−${euro(r.estimatedCosts)}</dd></div><div class="receipt-total"><dt>Nach geschätzten Fahrtkosten</dt><dd>${euro(r.net)}</dd></div>`:''}</dl>${r.estimatedCosts?'<p class="footnote">Fahrtkosten sind eine Rücklage für Tanken und Reparaturen. Sie werden hier nicht nochmals vom Bargeld abgezogen.</p>':''}<p>Zuverlässigkeit ${r.reliabilityDelta>=0?'+':''}${r.reliabilityDelta} · aktuell ${s.courier.reliability}/100</p></section>`;
}
